import { Scanner } from "tapirscan/browser";

const scanner = new Scanner({ mode: "medium", formats: "retail" });
try {
  const barcodes = await scanner.scan(image); // File, image, video or canvas.
  for (const barcode of barcodes) {
    console.log(barcode.text, barcode.format, barcode.polygon);
  }
} finally {
  scanner.dispose();
}

